    public static int stSortNums(emon.Port.Cells c) {
        // Shell sort of the numbers in `c`, ascending (Knuth's gaps).
        int n = emon.Port.cellsLen(c);
        int h = 1;
        int i = 0;
        int j = 0;
        int v = 0;
        int u = 0;
        int more = 1;
        while (h < (n / 3)) {
            h = (h * 3) + 1;
        }
        while (h >= 1) {
            i = h;
            while (i < n) {
                v = emon.Port.cellsAt(c, i);
                j = i;
                more = 1;
                while ((j >= h) && (more == 1)) {
                    u = emon.Port.cellsAt(c, j - h);
                    if (v < u) {
                        emon.Port.cellsSet(c, j, u);
                        j -= h;
                    } else {
                        more = 0;
                    }
                }
                emon.Port.cellsSet(c, j, v);
                i += 1;
            }
            h = (h - 1) / 3;
        }
        return 0;
    }
